"""Hands-on projects 1-4 (fully runnable locally with Python standard library, SQLite and DuckDB)."""
from __future__ import annotations

from typing import Any


def step(id: str, title: str, detail: str, code: str | None = None, lang: str = "python") -> dict[str, Any]:
    s: dict[str, Any] = {"id": id, "title": title, "detail": detail}
    if code:
        s["code"] = code.strip("\n")
        s["lang"] = lang
    return s


def ms(id: str, title: str, *steps: dict[str, Any]) -> dict[str, Any]:
    return {"id": id, "title": title, "steps": list(steps)}


